    berryGrow: {label:"University of Minnesota Extension — Growing strawberries", url:"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-strawberries-in-the-home-garden"},
    grapeGrow: {label:"University of Minnesota Extension — Growing grapes", url:"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-grapes-in-the-home-garden"},
    lettuceGrow: {label:"University of Minnesota Extension — Growing lettuce", url:"https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-lettuce-endive-and-radicchio"},
